-- =====================================================================
-- 0032 — Tarefas do Notion: 2º bloco (190 tarefas mais recentes)
-- Fonte: Notion "Controle de Tarefas" (12/05/2026 a 13/10/2026).
-- Pode rodar mais de uma vez (não duplica; usa notion_id).
-- Rode DEPOIS da 0026, 0027 e 0028 (colunas e enum já existem).
-- =====================================================================

alter table tarefas add column if not exists notion_id text unique;
alter table tarefas add column if not exists prioridade smallint;
alter table tarefas add column if not exists link text;
alter table tarefas add column if not exists tag text;
alter table tarefas add column if not exists responsaveis_notion text;
alter table tarefas add column if not exists status_notion text;

insert into tarefas
  (titulo, descricao, status, responsavel_id, prazo, created_at,
   notion_id, prioridade, link, tag, responsaveis_notion, status_notion)
select
  t.titulo,
  t.descricao,
  t.status::tarefa_status,
  (select p.id from profiles p
    where lower(p.email) = case t.resp_principal
      when 'J' then 'social.media@litoralverde.com.br'
      when 'S' then 'criacao@litoralverde.com.br'
      when 'T' then 'thiago.leal@litoralverde.com.br'
      when 'G' then 'gustavo.monken@litoralverde.com.br'
      else null end
    limit 1),
  t.prazo::timestamptz,
  t.criado::timestamptz,
  t.notion_id,
  t.prioridade,
  t.link,
  t.tag,
  t.responsaveis,
  t.status_notion
